import { computed } from 'vue';
/** 公共输入允许清空或多种标量，页面模型只接收自己声明的合法值。 */
export function choiceModel(read, write, choices) {
	return computed({
		get: read,
		set(value) {
			if (choices.some((choice) => Object.is(choice, value))) write(value);
		}
	});
}
export function booleanModel(read, write) {
	return computed({
		get: read,
		set(value) {
			if (typeof value === 'boolean') write(value);
		}
	});
}
export function textModel(read, write) {
	return computed({
		get: read,
		set(value) {
			if (typeof value === 'string') write(value);
		}
	});
}

import { computed, onBeforeUnmount, onMounted, shallowRef } from 'vue';
export function useDashboardMetricLayout(page) {
	const width = shallowRef(1440);
	const columns = computed(() => (width.value < 700 ? 1 : width.value < 1100 ? 2 : 4));
	let observer;
	onMounted(() => {
		const element = page.value;
		if (!element) return;
		const measure = () => {
			width.value = element.getBoundingClientRect().width;
		};
		measure();
		observer = new ResizeObserver(measure);
		observer.observe(element);
	});
	onBeforeUnmount(() => observer?.disconnect());
	return { width, columns };
}

import { reactive, shallowRef } from 'vue';
import { monitorRegions, monitorStreams } from './Types.js';
/** 本地源严格遵守已有SubscribeSource；不创建EventSource或真实接口。 */
export function createBusinessMonitorFixture() {
	const controls = reactive({
		mode: 'normal',
		delayMs: 80,
		identity: 1
	});
	const audit = reactive({ subscriptions: 0, closed: 0, active: 0, delivered: 0 });
	const cleanups = new Set();
	const source = {
		id: 'local-business-monitor',
		subscribe(sink) {
			++audit.subscriptions;
			++audit.active;
			let active = true,
				tick = 0,
				interval;
			const identity = controls.identity,
				mode = controls.mode,
				delay = controls.delayMs;
			function emit(stream, seq, value, at = Date.now()) {
				if (!active) return;
				++audit.delivered;
				sink.message({ stream, seq, at, value });
			}
			function frame() {
				const values = {
					online: 1286 + tick,
					processed: 9120 + (tick % 10) * 20,
					response: 1.8,
					success: 99.6,
					goal: 12000,
					current: 90,
					previous: 65,
					north: 3200,
					south: 2400,
					east: 1900,
					west: 1620,
					asset: 2846,
					workflow: 1927,
					knowledge: 1456,
					backlog: 128,
					assetChange: 12.6,
					workflowChange: 8.2,
					knowledgeChange: 6.8,
					backlogChange: -5.2
				};
				for (const stream of monitorStreams) {
					if (
						stream === 'current' ||
						stream === 'previous' ||
						monitorRegions.some((region) => region === stream)
					)
						continue;
					emit(
						stream,
						tick,
						mode === 'empty' || (mode === 'partial' && stream === 'response')
							? null
							: values[stream] * (stream === 'online' ? identity : 1)
					);
				}
				const length = tick === 0 ? 12 : 1;
				for (let i = 0; i < length; i++) {
					const seq = tick === 0 ? i : 11 + tick;
					const at = Date.now() - (length - i - 1) * 1000;
					monitorRegions.forEach((region, index) =>
						emit(
							region,
							seq,
							mode === 'empty' || (mode === 'partial' && region === 'east')
								? null
								: values[region] + ((seq % 12) - 11) * (index + 1) * 9,
							at
						)
					);
					emit(
						'current',
						seq,
						mode === 'empty'
							? null
							: [39, 62, 51, 84, 65, 93, 58, 78, 63, 88, 98, 73][seq % 12],
						at
					);
					emit(
						'previous',
						seq,
						mode === 'empty'
							? null
							: [30, 42, 44, 59, 48, 65, 50, 67, 46, 74, 79, 65][seq % 12],
						at
					);
				}
				++tick;
			}
			function close() {
				if (!active) return;
				active = false;
				clearTimeout(initial);
				if (interval) clearInterval(interval);
				++audit.closed;
				--audit.active;
				cleanups.delete(close);
			}
			const initial = setTimeout(() => {
				if (!active) return;
				if (mode === 'error') {
					sink.error();
					return;
				}
				sink.open();
				frame();
				interval = setInterval(frame, 1000);
			}, delay);
			cleanups.add(close);
			return { close };
		}
	};
	const host = shallowRef({ owner: { identity: 1 }, source });
	return {
		host,
		controls,
		audit,
		switchIdentity() {
			++controls.identity;
			host.value = { owner: { identity: controls.identity }, source };
		},
		dispose() {
			for (const close of [...cleanups]) close();
		}
	};
}

import { computed, onScopeDispose, shallowRef, watch } from 'vue';
import { createMonitor } from '../../visualization/Monitor.js';
import { businessValue, monitorStreams } from './Types.js';
/** 每页独立容器；只编排宿主变化，连接/时序/缓冲/取消仍由既有Monitor实现。 */
export function useBusinessMonitor(host) {
	const snapshot = shallowRef({
		state: 'idle',
		source: '',
		attempts: 0,
		dropped: 0,
		lastAt: null,
		points: {}
	});
	let monitor;
	let disposed = false;
	watch(
		() => [host().owner, host().source],
		() => {
			monitor?.dispose();
			monitor = createMonitor(
				{
					streams: [...monitorStreams],
					capacity: 60,
					intervalMs: 1000,
					batchMs: 100,
					reconnects: 0
				},
				(value) => {
					snapshot.value = value;
				}
			);
			snapshot.value = monitor.snapshot();
			monitor.start(host().source);
		},
		{ immediate: true, flush: 'sync' }
	);
	const visible = computed(() =>
		['live', 'paused', 'stale'].includes(snapshot.value.state) ? snapshot.value : undefined
	);
	const available = computed(() =>
		monitorStreams.some((id) => businessValue(visible.value, id) !== null)
	);
	const status = computed(() =>
		'error' === snapshot.value.state
			? 'error'
			: ['idle', 'connecting', 'reconnecting'].includes(snapshot.value.state)
				? 'loading'
				: available.value
					? 'ready'
					: 'empty'
	);
	const partial = computed(
		() =>
			available.value &&
			monitorStreams.some((id) => businessValue(visible.value, id) === null)
	);
	onScopeDispose(() => {
		disposed = true;
		monitor?.dispose();
		snapshot.value = {
			state: 'closed',
			source: '',
			attempts: 0,
			dropped: 0,
			lastAt: null,
			points: {}
		};
	});
	return {
		snapshot: computed(() => snapshot.value),
		visible,
		status,
		partial,
		pause: () => monitor?.pause(),
		resume: () => monitor?.resume(),
		reconnect: () => monitor?.reconnect(),
		close: () => monitor?.close(),
		resources: () => monitor?.resources(),
		get disposed() {
			return disposed;
		}
	};
}

export const monitorRegions = ['north', 'south', 'east', 'west'];
export const monitorStreams = [
	'online',
	'processed',
	'response',
	'success',
	'goal',
	'current',
	'previous',
	...monitorRegions,
	'asset',
	'workflow',
	'knowledge',
	'backlog',
	'assetChange',
	'workflowChange',
	'knowledgeChange',
	'backlogChange'
];
/** 空或业务范围不合法的值保持缺失，不将缺失补成零。 */
export function businessValue(snapshot, stream) {
	const value = snapshot?.points[stream]?.at(-1)?.value;
	if (value === undefined || value === null || !Number.isFinite(value)) return null;
	if (!stream.endsWith('Change') && value < 0) return null;
	if (stream === 'success' && value > 100) return null;
	return value;
}

import { createApp, shallowRef } from 'vue';
import { provideAsamData } from '@asam-ui/ui';
import { AsamI18nKey, createAsamI18n } from '@asam-ui/ui/i18n';
import App from './App.vue';
/** 演示宿主拥有本地源；外部语言实例仍归调用者。 */
export function mountMonitorWorkspace(element, host, onError) {
	const locale = shallowRef('zh-CN');
	const i18n = host?.i18n ?? createAsamI18n(() => ({ locale: locale.value }));
	const app = createApp(App, {
		externalI18n: host?.i18n,
		inheritAppearance: host?.inheritAppearance,
		diagnostics: host?.diagnostics,
		onLocale: (value) => {
			locale.value = value;
		}
	});
	app.provide(AsamI18nKey, i18n);
	provideAsamData(app, {}, { scope: 'dashboard-monitor-demo' });
	if (onError) app.config.errorHandler = onError;
	app.mount(element);
	let disposed = false;
	return () => {
		if (disposed) return;
		disposed = true;
		app.unmount();
		if (!host?.i18n) i18n.dispose();
	};
}

/** Validate before invoking the engine. Null is a gap, zero and signed decimals are values. */
export function validateSeries(series, scope) {
	const ids = new Set();
	for (const item of series) {
		if (!item.id || ids.has(item.id))
			return scope?.enabled.value
				? scope.t('app.templates.visualization.seriesId')
				: 'series ID 缺失或重复';
		ids.add(item.id);
		if (!['line', 'bar', 'pie'].includes(item.kind))
			return scope?.enabled.value
				? scope.t('app.templates.visualization.chartKind')
				: '未注册的图表类型';
		const points = new Set();
		for (const point of item.points) {
			if (!point.id || points.has(point.id))
				return scope?.enabled.value
					? scope.t('app.templates.visualization.pointId')
					: 'point ID 缺失或重复';
			points.add(point.id);
			if (point.value !== null && !Number.isFinite(point.value))
				return scope?.enabled.value
					? scope.t('app.templates.visualization.finite')
					: '图表值必须为有限数字或 null';
			if (item.kind === 'pie' && point.value !== null && point.value < 0)
				return scope?.enabled.value
					? scope.t('app.templates.visualization.negativePie')
					: '饼图不支持负数；请使用折线或柱图';
		}
	}
}

import { init, use } from 'echarts/core';
import { LineChart, BarChart, PieChart } from 'echarts/charts';
import {
	GridComponent,
	TooltipComponent,
	LegendComponent,
	DataZoomComponent,
	AriaComponent
} from 'echarts/components';
import { SVGRenderer } from 'echarts/renderers';
use([
	LineChart,
	BarChart,
	PieChart,
	GridComponent,
	TooltipComponent,
	LegendComponent,
	DataZoomComponent,
	AriaComponent,
	SVGRenderer
]);
export { init };

/** Vite resolves this marker to its own emitted entry, including the configured base URL.
 * A fresh URL on retry avoids the browser's cached rejected dynamic-import promise.
 * No remote scripts, copied engine code or alternate dependency instance are used.
 */
let loaded;
export async function loadEngine(attempt) {
	if (loaded) return loaded;
	const url = new URL('__ASAM_ENGINE_URL__', import.meta.url);
	if (attempt > 0) url.searchParams.set('asam-retry', String(attempt));
	const engine = await import(/* @vite-ignore */ url.href);
	loaded = engine;
	return engine;
}

import { createAsamMessageError } from '@asam-ui/pro/i18n';
function bounded(value, fallback, min, max) {
	return value === undefined
		? fallback
		: Number.isFinite(value)
			? Math.min(max, Math.max(min, Math.trunc(value)))
			: fallback;
}
/** One controller per mounted page. No global pool, background wakeup or unbounded queue. */
export function createMonitor(options, changed) {
	if (!options.streams.length || new Set(options.streams).size !== options.streams.length)
		throw createAsamMessageError(
			new TypeError('唯一流 ID 必填'),
			'app.templates.visualization.streamRequired'
		);
	const capacity = bounded(options.capacity, 600, 1, 600);
	const interval = bounded(options.intervalMs, 100, 50, 60_000);
	const batch = bounded(options.batchMs, 100, 100, 10_000);
	const retries = bounded(options.reconnects, 3, 0, 10);
	const backoff = bounded(options.backoffMs, 1000, 100, 10_000);
	let state = 'idle';
	let source;
	let subscription;
	let request;
	let generation = 0;
	let attempts = 0;
	let dropped = 0;
	let lastAt = null;
	let receivedAt = 0;
	let startedAt = 0;
	let destroyed = false;
	const timers = new Set();
	const points = Object.fromEntries(options.streams.map((id) => [id, []]));
	const pending = Object.fromEntries(options.streams.map((id) => [id, []]));
	const sequences = new Map();
	let flushing = false;
	function snapshot() {
		return {
			state,
			source: source?.id ?? '',
			attempts,
			dropped,
			lastAt,
			points: Object.fromEntries(options.streams.map((id) => [id, points[id].slice()]))
		};
	}
	function publish() {
		if (!destroyed) changed(snapshot());
	}
	function schedule(fn, delay, token) {
		const timer = setTimeout(() => {
			timers.delete(timer);
			if (!destroyed && token === generation) fn();
		}, delay);
		timers.add(timer);
	}
	function cleanup() {
		++generation;
		for (const timer of timers) clearTimeout(timer);
		timers.clear();
		flushing = false;
		const old = subscription;
		subscription = undefined;
		old?.close();
		const oldRequest = request;
		request = undefined;
		oldRequest?.abort();
		for (const id of options.streams) {
			dropped += pending[id].length;
			pending[id] = [];
		}
	}
	function accept(point, token) {
		if (token !== generation || destroyed) return;
		if (typeof point !== 'object' || point === null) {
			dropped++;
			return;
		}
		if (
			!Object.hasOwn(points, point.stream) ||
			!Number.isSafeInteger(point.seq) ||
			point.seq < 0 ||
			!Number.isFinite(point.at) ||
			(point.value !== null && !Number.isFinite(point.value))
		) {
			dropped++;
			return;
		}
		if (point.seq <= (sequences.get(point.stream) ?? -1)) {
			dropped++;
			return;
		}
		sequences.set(point.stream, point.seq);
		const queue = pending[point.stream];
		queue.push({ ...point });
		if (queue.length > capacity) {
			queue.shift();
			dropped++;
		}
		receivedAt = Date.now();
		lastAt = point.at;
		state = 'live';
		if (!flushing) {
			flushing = true;
			schedule(
				() => {
					flushing = false;
					for (const id of options.streams) {
						const all = [...points[id], ...pending[id]];
						dropped += Math.max(0, all.length - capacity);
						points[id] = all.slice(-capacity);
						pending[id] = [];
					}
					publish();
				},
				batch,
				token
			);
		}
	}
	function staleWatch(token) {
		schedule(
			() => {
				if (
					['connecting', 'live', 'stale'].includes(state) &&
					Date.now() - (receivedAt || startedAt) > interval * 3
				) {
					state = 'stale';
					publish();
				}
				staleWatch(token);
			},
			interval,
			token
		);
	}
	function connect(isRetry = false) {
		if (!source || destroyed) return;
		cleanup();
		sequences.clear();
		receivedAt = 0;
		startedAt = Date.now();
		for (const id of options.streams) points[id] = [];
		const token = generation;
		state = isRetry ? 'reconnecting' : 'connecting';
		publish();
		staleWatch(token);
		if ('subscribe' in source) {
			let failed = false;
			const fail = () => {
				if (token !== generation || failed || destroyed) return;
				failed = true;
				cleanup();
				if (attempts >= retries) {
					state = 'error';
					publish();
					return;
				}
				const delay = Math.min(10_000, backoff * 2 ** attempts++);
				state = 'reconnecting';
				publish();
				schedule(() => connect(true), delay, generation);
			};
			try {
				const created = source.subscribe({
					open() {
						if (token === generation && !failed) {
							state = 'live';
							publish();
						}
					},
					message: (p) => accept(p, token),
					error: fail
				});
				if (token === generation && !failed) subscription = created;
				else created.close();
			} catch {
				fail();
			}
		} else {
			const pollSource = source;
			async function poll() {
				const controller = new AbortController();
				request = controller;
				try {
					const data = await pollSource.poll(controller.signal);
					if (token !== generation) return;
					data.forEach((p) => accept(p, token));
				} catch {
					if (token === generation && !controller.signal.aborted) {
						state = 'error';
						publish();
					}
				} finally {
					if (request === controller) request = undefined;
					if (token === generation && !destroyed)
						schedule(() => void poll(), interval, token);
				}
			}
			void poll();
		}
	}
	return {
		start(next) {
			if (destroyed) return;
			cleanup();
			source = next;
			attempts = 0;
			lastAt = null;
			for (const id of options.streams) points[id] = [];
			connect();
		},
		pause() {
			if (destroyed) return;
			cleanup();
			state = 'paused';
			publish();
		},
		resume() {
			if (!destroyed && state === 'paused') {
				attempts = 0;
				connect();
			}
		},
		reconnect() {
			if (!destroyed) {
				attempts = 0;
				connect();
			}
		},
		close() {
			if (destroyed) return;
			cleanup();
			state = 'closed';
			publish();
		},
		dispose() {
			cleanup();
			state = 'closed';
			destroyed = true;
		},
		snapshot,
		resources: () => ({
			timers: timers.size,
			subscription: !!subscription,
			request: !!request,
			pending: Object.values(pending).reduce((n, p) => n + p.length, 0)
		})
	};
}

